mUtils.skillBookUse(target, xi.skill.DARK_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_death_for_dimwits.lua"]={["Path"]="scripts/items/copy_of_death_for_dimwits.lua",["SHA256"]="6ed6ea6f5c32d687f87a2b3875870946b0f070a4ea0b592235ac88c855f0beb7",["Text"]="-----------------------------------\n-- ID: 6152\n-- Item: Death for Dimwits\n-- A guide to the finer points of hacking everything in one's way to pieces with a two-handed axe,\n-- written by an anonymous individual.\n-- Adventurers note that reading it increases one's great axe skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.GREAT_AXE)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.GREAT_AXE)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_ferreouss_diary.lua"]={["Path"]="scripts/items/copy_of_ferreouss_diary.lua",["SHA256"]="0c64e69bd85649c76418a54d349d3d18df33cbcd5e88cd1a497eb6945b7235c4",["Text"]="-----------------------------------\n-- ID: 6157\n-- Item: Ferreous's Diary\n-- A diary written by Ferreous Coffin that describes his encounters with Orcs in the north.\n-- So many were there that his war hammer became coated with a thick layer of blood after all was said and done.\n-- Adventurers note that reading it increases one's club skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.CLUB)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.CLUB)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_ginuvas_battle_theory.lua"]={["Path"]="scripts/items/copy_of_ginuvas_battle_theory.lua",["SHA256"]="55b860bd742176ed8ba432417a4578d45bd75ebeb5bfeeed6dc79b663e5e7b3f",["Text"]="-----------------------------------\n-- ID: 4248\n-- Item: Copy of \"Ginuva's Battle Theory\"\n-- Grants 75 - 200 EXP\n-- Source: https://wiki.ffo.jp/html/8068.html\n-- Does not grant Limit Points.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local check = 56\n    if target:getMainLvl() >= 65 then\n        check = 0\n    end\n\n    return check\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local exp = xi.settings.main.EXP_RATE * math.randomInt(75, 200)\n\n    target:addExp(exp, false)\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EXP_GAINED)\n\n    -- Show the full EXP amount even when EXP is capped.\n    return exp\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_hrohjs_record.lua"]={["Path"]="scripts/items/copy_of_hrohjs_record.lua",["SHA256"]="538242522658490c1e45b9f6610fecb299f3e2f37d8e7334cbba52b9cb3ba1cd",["Text"]="-----------------------------------\n-- ID: 6178\n-- Item: Hrohj's Record\n-- A record of what happened on the fateful day the lifestream overflowed,\n-- as kept by Hrohj Wagrehsa.\n-- Adventurers note that reading it increases one's geomancy skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.GEOMANCY)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.GEOMANCY)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_kagetoras_diary.lua"]={["Path"]="scripts/items/copy_of_kagetoras_diary.lua",["SHA256"]="19f870703a3afc43331d69ee4e213ef9799e5c60a191dcd48e3c25eb1aa7c50e",["Text"]="-----------------------------------\n-- ID: 6155\n-- Item: Kagetora's Diary\n-- A diary written by Kagetora.\n-- In it he details each and every one of his ninety-eight victories and ninety-nine losses against Yomi.\n-- Adventurers note that reading it increases one's katana skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.KATANA)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.KATANA)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_kagetoras_journal.lua"]={["Path"]="scripts/items/copy_of_kagetoras_journal.lua",["SHA256"]="784f7d18cdf762aba66f57a8d4d37eeb700c667595f384bebaba702f54259968",["Text"]="-----------------------------------\n-- ID: 6165\n-- Item: Kage. Journal\n-- A journal kept by Kagetora that delineates the extent to which\n-- he and Yomi lost themselves in their studies of the martial arts\n-- Adventurers note that reading it increases one's parrying skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.PARRY)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.PARRY)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_kayeel-payeels_memoirs.lua"]={["Path"]="scripts/items/copy_of_kayeel-payeels_memoirs.lua",["SHA256"]="f33d61e015a8d86f5886bd2e8c8e0efc325994e72b9b58267de2743bcde1cb6b",["Text"]="-----------------------------------\n-- ID: 6158\n-- Item: K-P's Memoirs\n-- Memoirs penned by Kayeel-Payeel.\n-- They describe in particular detail the time he received Claustrum from the Warlock Warlord Robel-Akbel.\n-- Adventurers note that reading them increases one's staff skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.STAFF)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.STAFF)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_life-form_study.lua"]={["Path"]="scripts/items/copy_of_life-form_study.lua",["SHA256"]="1fc091acd715d1983e61708a3283b291c40978b956575d3fd81b5d7aa75bf16f",["Text"]="-----------------------------------\n-- ID: 6177\n-- Item: Life-form Study\n-- A report written and filed by an anonymous individual.\n-- It covers the behavioral patterns and diets of almost every known family of beasts in existence.\n-- Adventurers note that reading it increases one's blue magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.BLUE_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.BLUE_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_ludwigs_report.lua"]={["Path"]="scripts/items/copy_of_ludwigs_report.lua",["SHA256"]="92ea0b0e4dc0a19d7fdcdf33c85e5f23e31106e40f9ab0b76c25a326fe31cf9d",["Text"]="-----------------------------------\n-- ID: 6153\n-- Item: Ludwig's Report\n-- A report made by Ludwig Eichberg regarding the Battle of Grauberg.\n-- It details the constant changes in the position of the front line and the withdrawal of Republic troops.\n-- Adventurers note that reading it increases one's scythe skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.SCYTHE)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.SCYTHE)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_mieuseloirs_diary.lua"]={["Path"]="scripts/items/copy_of_mieuseloirs_diary.lua",["SHA256"]="4b79dd4d15b93179f15896440be5b5c565a6dd1dc7b45b1f7644c415c33805ed",["Text"]="-----------------------------------\n-- ID: 6150\n-- Item: Mieuseloir's Diary\n-- An account penned by Mieuseloir B Enchelles of his encounters with the Gigas in Beaucedine Glacier.\n-- Adventurers note that reading it increases one's great sword skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.GREAT_SWORD)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.GREAT_SWORD)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_mikhes_memo.lua"]={["Path"]="scripts/items/copy_of_mikhes_memo.lua",["SHA256"]="e0f88118720bec7c74dab8b029d57f2e2b0c0714338f188b312a6b1f8dc55528",["Text"]="-----------------------------------\n-- ID: 6147\n-- Item: Mikhe's Memo\n-- A memo scrawled by Mikhe Aryohcha that matter-of-factly states,\n-- \"Just throw your fist at your opponent and it'll all work out.\"\n-- Adventurers say that their hand-to-hand skill increases after reading this note.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.HAND_TO_HAND)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.HAND_TO_HAND)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_mikhes_note.lua"]={["Path"]="scripts/items/copy_of_mikhes_note.lua",["SHA256"]="6f9cbad2fed41e60807993a00fd197dfbcdcea4aff30981f7d1a0d90baaed09c",["Text"]="-----------------------------------\n-- ID: 6162\n-- Item: Mikhe's Note\n-- A memo scrawled by Mikhe Aryohcha that matter-of-factly states,\n-- \"Just throw your guard up and it'll all work out.\"\n-- Adventurers note that reading it increases one's guarding skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.GUARD)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.GUARD)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_noilluries_log.lua"]={["Path"]="scripts/items/copy_of_noilluries_log.lua",["SHA256"]="94df28f5ab388585e42f0ddabd0c764e064f3e8551029e2e3523049c504b1025",["Text"]="-----------------------------------\n-- ID: 6156\n-- Item: Noillurie's Log\n-- A record Noillurie kept of her personal experiences.\n-- The one that stands out the most is the battle with the colossal beast she undertook to prove herself to her order.\n-- Adventurers note that reading it increases one's great katana skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.GREAT_KATANA)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.GREAT_KATANA)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_perihs_primer.lua"]={["Path"]="scripts/items/copy_of_perihs_primer.lua",["SHA256"]="d1f35fef39776339cf0e4f6ab05935116e1052343b232b66ecf6c6e56624e639",["Text"]="-----------------------------------\n-- ID: 6159\n-- Item: Perih's Primer\n-- A guidebook Perih Vashai jotted down for the edification of new recruits.\n-- It discusses everything from the various ways of holding a bow to methods of judging distance.\n-- Adventurers note that reading it increases one's archery skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.ARCHERY)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.ARCHERY)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_schultz_stratagems.lua"]={["Path"]="scripts/items/copy_of_schultz_stratagems.lua",["SHA256"]="44d82062452a4a7bbaad0e80e57e5e8c37da05d74ee16ad3e773bf96ee6945c7",["Text"]="-----------------------------------\n-- ID: 4249\n-- Item: Copy of Schultz Stratage\n-- Grants 200 - 500 EXP\n-- Source: https://wiki.ffo.jp/html/8070.html\n-- Does not grant Limit Points.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local check = 56\n    if target:getMainLvl() >= 65 then\n        check = 0\n    end\n\n    return check\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local exp = xi.settings.main.EXP_RATE * math.randomInt(200, 500)\n\n    target:addExp(exp, false)\n    action:messageID(target:getID(), xi.msg.basic.ITEM_EXP_GAINED)\n\n    -- Show the full EXP amount even when EXP is capped.\n    return exp\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_sonias_diary.lua"]={["Path"]="scripts/items/copy_of_sonias_diary.lua",["SHA256"]="9ca70cc7c9d52284e21b1b3e4a930d594dd67fe608e90df6d330e7af91d0023c",["Text"]="-----------------------------------\n-- ID: 6163\n-- Item: Sonia's Diary\n-- A compilation of memories from Sonia. Of particular note are her observations\n-- on how to replicate the sheer brilliance of Annika Brilioth and the esoteric steps known as the Kriegstanz.\n-- Adventurers say that reading it increases their evasion skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.EVASION)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.EVASION)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_striking_bulls_diary.lua"]={["Path"]="scripts/items/copy_of_striking_bulls_diary.lua",["SHA256"]="68f98afbe5e0f5da9141f956105c9593d92f67253887c9778313410ac41b3e0e",["Text"]="-----------------------------------\n-- ID: 6151\n-- Item: Bull's Diary\n-- An account penned by Striking Bull during the Second Battle of Konschtat.\n-- It details the Republic's victory over King Raigegue the Lupine's San d'Orian army.\n-- Adventurers note that reading it increases one's axe skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.AXE)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.AXE)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_swing_and_stab.lua"]={["Path"]="scripts/items/copy_of_swing_and_stab.lua",["SHA256"]="f3d413febf1a8857e16fc3f5fe195a0feef84319a5abadec4c74a5a86d7f9441",["Text"]="-----------------------------------\n-- ID: 6149\n-- Item: Swing and Stab\n-- Ulla wrote this guide on sword wielding\n-- from how to grip the hilt to tips on footwork\n-- so others could follow in her footsteps.\n-- Adventurers note that reading it increases one's sword skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.SWORD)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.SWORD)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_the_bell_tolls.lua"]={["Path"]="scripts/items/copy_of_the_bell_tolls.lua",["SHA256"]="ba38c45b03a4b5237c9f4cf52d7805e4801e9cede40a7a85af855654f554dee1",["Text"]="-----------------------------------\n-- ID: 6179\n-- Item: The Bell Tolls\n-- An essay penned by Hrohj Wagrehsa concerning the transmission of Sih Renaye's handbell and the voice of the land.\n-- Adventurers note that reading it increases one's handbell skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.HANDBELL)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.HANDBELL)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_the_successor.lua"]={["Path"]="scripts/items/copy_of_the_successor.lua",["SHA256"]="929a894e3c3e32954abf1fa6f38a489d586510e1752854eeddc2f883e6f6bd5f",["Text"]="-----------------------------------\n-- ID: 6164\n-- Item: The Successor\n-- An essay authored by Cerane I Virgaut,\n-- mainly concerning the night Perseus bequeathed unto her an exemplary shield.\n-- Adventurers note that reading it increases one's shield skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.SHIELD)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.SHIELD)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_yomis_diagram.lua"]={["Path"]="scripts/items/copy_of_yomis_diagram.lua",["SHA256"]="b1c7cab03d98e16519f022f93624160353332615fb5e85001f61df22b2e814f7",["Text"]="-----------------------------------\n-- ID: 6175\n-- Item: Yomi's Diagram\n-- A meticulously drawn diagram Yomi made for Kagetora explaining how to construct certain ninja tools.\n-- Adventurers note that reading it increases one's ninjutsu skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.NINJUTSU)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.NINJUTSU)\nend\n\nreturn itemObject\n"},["scripts/items/coral_butterfly.lua"]={["Path"]="scripts/items/coral_butterfly.lua",["SHA256"]="7ca8f2b0a83f8efef4eb1a68782329f4e84116ed5ad917211c06947a2a7c076c",["Text"]="-----------------------------------\n-- ID: 4580\n-- Item: Coral Butterfly\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coral_fungus.lua"]={["Path"]="scripts/items/coral_fungus.lua",["SHA256"]="42610da9d8564a98ac762ee389138139bd1bb432d91f23d40e404ac292aab56a",["Text"]="-----------------------------------\n-- ID: 4450\n-- Item: coral_fungus\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -4\n-- Mind 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -4)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coral_sword.lua"]={["Path"]="scripts/items/coral_sword.lua",["SHA256"]="7ff1f462b32d0aa99983ac471a2f775dd86793103f90c793a36965e081c26a3f",["Text"]="-----------------------------------\n-- ID: 16548\n-- Item: Coral Sword\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = utils.clamp(dStat / 2, 0, 54) -- Kinda jank looking, but it sort of aligns. Need more data.\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 0.186, 0, 10), -- 0-10% over 54 dINT, approx.\n        basePower      = math.randomInt(power + 6, power + 9),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/corsair_bullet_pouch.lua"]={["Path"]="scripts/items/corsair_bullet_pouch.lua",["SHA256"]="71817d9fbd5d14c1cbc42fb2b2f42fe2a641f790ed63cc280241c88554c1cc26",["Text"]="-----------------------------------\n-- ID: 5342\n-- Corsair Bullet Pouch\n-- When used, you will obtain one stack of Corsair Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CORSAIR_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/corsair_die.lua"]={["Path"]="scripts/items/corsair_die.lua",["SHA256"]="767be6ebbe2199019cdd8b29b53fb8254aafa715574d1f513b6e175ebcfdf37e",["Text"]="-----------------------------------\n-- ID: 5493\n-- Corsair Die\n-- Teaches the job ability Corsair's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.CORSAIRS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.CORSAIRS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/cotton_coin_purse.lua"]={["Path"]="scripts/items/cotton_coin_purse.lua",["SHA256"]="e8d34068968aca9da8f89a074251119872a82de0bb6094da7710e76a197ca9b9",["Text"]="-----------------------------------\n-- ID: 5735\n-- Ctn. Purse (Alx.)\n-- Breaks up a Cotton Purse\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ALEXANDRITE, math.randomInt(5, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/cougar_baghnakhs.lua"]={["Path"]="scripts/items/cougar_baghnakhs.lua",["SHA256"]="3da1b5e6b8a8887b443ffbf2f768b6f513157f9650b827b66fb116ec553f998f",["Text"]="-----------------------------------\n-- ID: 16702\n-- Item: Cougar Baghnakhs\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/counter_earring.lua"]={["Path"]="scripts/items/counter_earring.lua",["SHA256"]="0318d9e7aa3e3c2d4b260e34414f12fb32927929a940c484614cf0fd82820391",["Text"]="-----------------------------------\n-- ID: 14786\n-- Item: Counter Earring\n-- Item Effect: Counter 5%\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10066.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.COUNTER_EARRING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.COUNTER_EARRING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.COUNTER_EARRING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.COUNTER, 5)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.COUNTER_EARRING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coursers_die.lua"]={["Path"]="scripts/items/coursers_die.lua",["SHA256"]="f69330305874b7db88074f24bac14720c1fcbd57f672b3dd75da3848e6f2018d",["Text"]="-----------------------------------\n-- ID: 104\n-- Courser's Die\n-- Teaches the job ability Coursers Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.COURSERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.COURSERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/crab_stewpot.lua"]={["Path"]="scripts/items/crab_stewpot.lua",["SHA256"]="0948888a06e62dfd5067b5b599a235247954bf02a2516d4b3dc4e5d8bbbe8937",["Text"]="-----------------------------------\n-- ID: 5544\n-- Item: Crab Stewpot\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% Cap 50\n-- MP +10\n-- HP Recoverd while healing 5\n-- MP Recovered while healing 1\n-- Defense +20% Cap 50\n-- Evasion +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 50)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_DEFP, 20)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cracker.lua"]={["Path"]="scripts/items/cracker.lua",["SHA256"]="349bb4b6d5480e6ac4916ec280bc9b4c5644a30cec5ba98327bb4c1a21318803",["Text"]="-----------------------------------\n-- ID: 4167\n-- Cracker\n-- Creates a simple puff of smoke with a \"crack\" noise\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/crackler.lua"]={["Path"]="scripts/items/crackler.lua",["SHA256"]="c03ef90641b1413a14f1de6a75bd602b9d54e2d09b4762947130facedb5a2a8e",["Text"]="-----------------------------------\n-- ID: 4250\n-- Crackler\n-- Bursts of light appear in front of the user with a crackling sound, with the word \"Congratulations!\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/crawler_egg.lua"]={["Path"]="scripts/items/crawler_egg.lua",["SHA256"]="2158462f873f42df480344786b4652eb80ae76b9579931cf3c128a79c06b5538",["Text"]="-----------------------------------\n-- ID: 4357\n-- Item: crawler_egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 10\n-- Magic 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/crayfish.lua"]={["Path"]="scripts/items/crayfish.lua",["SHA256"]="22e3e988fde2102118a16b7b0b9f853dd92a498772d2f3ba6401666e59622a35",["Text"]="-----------------------------------\n-- ID: 4472\n-- Item: crayfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -3\n-- Vitality 1\n-- defense +10% (unknown cap)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -3)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.FOOD_DEFP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cream_puff.lua"]={["Path"]="scripts/items/cream_puff.lua",["SHA256"]="369293fbd63ac47779be5f5682ad0a790d50acb43906bfda5c3b698e6525bd51",["Text"]="-----------------------------------\n-- ID: 5718\n-- Item: Cream Puff\n-- Food Effect: 30 mintutes, All Races\n-----------------------------------\n-- Intelligence +7\n-- HP -10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 7)\n    effect:addMod(xi.mod.FOOD_HP, -10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/creek_maillot_+1.lua"]={["Path"]="scripts/items/creek_maillot_+1.lua",["SHA256"]="62db35c3e343881f11a94f5fc8df5ef0d3c0cd799f983122e91a241f6ca2bd82",["Text"]="-----------------------------------\n-- ID: 10268\n-- Creek Maillot +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/creek_top_+1.lua"]={["Path"]="scripts/items/creek_top_+1.lua",["SHA256"]="80e762cb51237e2b25049e3a6da916b9258d4800af927c62fc3e49516b7369cd",["Text"]="-----------------------------------\n-- ID: 10269\n-- Creek Top +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/creel_of_forest_carp.lua"]={["Path"]="scripts/items/creel_of_forest_carp.lua",["SHA256"]="a03fbe5e2dad0e64afc512be72afc18cf56ef3adae55a1e33beddfcbb333710f",["Text"]="-----------------------------------\n-- ID: 5811\n-- Item: Creel of Forest Carp\n-- When used, you will obtain 6-12 Forest Carp\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FOREST_CARP, math.randomInt(6, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/creel_of_moat_carp.lua"]={["Path"]="scripts/items/creel_of_moat_carp.lua",["SHA256"]="8ca86332ed117de3da77c43db27619feb43a5197da00962f429f37134c2f3a3a",["Text"]="-----------------------------------\n-- ID: 5810\n-- Item: Creel of Moat Carp\n-- When used, you will obtain 6-12 Moat Carp\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MOAT_CARP_1, math.randomInt(6, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/crepe_belle_helene.lua"]={["Path"]="scripts/items/crepe_belle_helene.lua",["SHA256"]="c5910b73e1624139068b628bc07c43311b14a2f606df7a18aa9000d7882aa314",["Text"]="-----------------------------------\n-- ID: 5778\n-- Item: Crepe Belle Helene\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- Intelligence +2\n-- MP Healing +3\n-- Magic Accuracy +21% (cap 50)\n-- Magic Defense +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MPHEAL, 3)\n    effect:addMod(xi.mod.FOOD_MACCP, 21)\n    effect:addMod(xi.mod.FOOD_MACC_CAP, 50)\n    effect:addMod(xi.mod.MDEF, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/crepe_caprice.lua"]={["Path"]="scripts/items/crepe_caprice.lua",["SHA256"]="640a337ec167b1a631cd390ac03e7d3282cb8a88a120a8dbbf58f8b5c6776770",["Text"]="-----------------------------------\n-- ID: 5776\n-- Item: Crepe Caprice\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP +5% (cap20)\n-- MP Healing 3\n-- Magic Accuracy +21% (cap 40)\n-- Magic Defense +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 5)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 20)\n    effect:addMod(xi.mod.MPHEAL, 3)\n    effect:addMod(xi.mod.MDEF, 2)\n    effect:addMod(xi.mod.FOOD_MACCP, 21)\n    effect:addMod(xi.mod.FOOD_MACC_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/crepe_delice.lua"]={["Path"]="scripts/items/crepe_delice.lua",["SHA256"]="177df1148f37b129ead9ab86f1cab3c46dfc6d1e1cda368f9df8e86e430239b3",["Text"]="-----------------------------------\n-- ID: 5767\n-- Item: Crepe Delice\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP +10% (cap 15)\n-- Magic Accuracy +21% (cap 30)\n-- Magic Defense +2\n-----------------------------------\n-