HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 30)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.MACC, 15)\n    effect:addMod(xi.mod.MDEF, 4)\n    effect:addMod(xi.mod.HPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/crescent_fish.lua"]={["Path"]="scripts/items/crescent_fish.lua",["SHA256"]="765ad52c05a742d8d2b516807ebd1603c3b0b4a39c41cd4c94e033444aa66663",["Text"]="-----------------------------------\n-- ID: 4473\n-- Item: crescent_fish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cryohelix_schema.lua"]={["Path"]="scripts/items/cryohelix_schema.lua",["SHA256"]="9037c3fc694628f97465f6dca32f77e758936bc62d6f836312d8d000f4e8f0c3",["Text"]="-----------------------------------\n-- ID: 6044\n-- Cryohelix Schema\n-- Teaches the black magic Cryohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.CRYOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.CRYOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/cube_of_cotton_tofu.lua"]={["Path"]="scripts/items/cube_of_cotton_tofu.lua",["SHA256"]="06a5de0d354eb6a796a38ffc8fd3e5519b46aca3b141f6029d225f5beda3e7e1",["Text"]="-----------------------------------\n-- ID: 5233\n-- Item: cube_of_cotton_tofu\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health % 10\n-- Health Cap 30\n-- Magic % 10\n-- Magic Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 30)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/culinarians_belt.lua"]={["Path"]="scripts/items/culinarians_belt.lua",["SHA256"]="3343b4be214c9fc90cbfe6c70acdadc4ee0320112879ff6d04e904c8958efa2c",["Text"]="-----------------------------------\n-- ID: 15451\n-- Item: Culinarian's Belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Cooking Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.COOKING_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COOKING_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/cumulus_cell.lua"]={["Path"]="scripts/items/cumulus_cell.lua",["SHA256"]="147bba10f5eeaef590b591e29c1e1e48ba6019793a925fac109804daae489522",["Text"]="-----------------------------------\n-- Cumulus Cell\n-- ID 5367\n-- Unlocks body equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x0020)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x0020, 2)\nend\n\nreturn itemObject\n"},["scripts/items/cumulus_masque_+1.lua"]={["Path"]="scripts/items/cumulus_masque_+1.lua",["SHA256"]="05cbfc80f90285835a288c41af3d510b701dfc2a6bedf73f175717cb69ad3b80",["Text"]="-----------------------------------\n-- ID: 10385\n-- Item: Cumulus Masque +1\n-- Teleport's user to the place of parting (Resienjima)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.REISENJIMA) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.CUMULUS_MASQUE, duration = 8, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/cup_of_caravan_tea.lua"]={["Path"]="scripts/items/cup_of_caravan_tea.lua",["SHA256"]="0745c83e611732190a4b622bb382f3bf50111ace3d7950efefc1cbfd3880dec4",["Text"]="-----------------------------------\n-- ID: 5927\n-- Item: Cup of Caravan Tea\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- HP 22\n-- MP 32\n-- Charisma 6\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 22)\n    effect:addMod(xi.mod.FOOD_MP, 32)\n    effect:addMod(xi.mod.CHR, 6)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cup_of_chai.lua"]={["Path"]="scripts/items/cup_of_chai.lua",["SHA256"]="0ea1fa17260474428765013c8672104de02898d6f2a789548e844bde37492495",["Text"]="-----------------------------------\n-- ID: 5570\n-- Item: cup_of_chai\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Vitality -2\n-- Charisma 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.CHR, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cup_of_chai_+1.lua"]={["Path"]="scripts/items/cup_of_chai_+1.lua",["SHA256"]="d1b942b6ba120a52cee3ec8c4c4ad9637ded7291004959c0d78fd4afb996ee3f",["Text"]="-----------------------------------\n-- ID: 5594\n-- Item: cup_of_chai_+1\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Vitality -3\n-- Charisma 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, -3)\n    effect:addMod(xi.mod.CHR, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cup_of_chamomile_tea.lua"]={["Path"]="scripts/items/cup_of_chamomile_tea.lua",["SHA256"]="78f565ceaa4725dfd8abd8f187c40473ef63a1735dbfcbf5fab2d525e4c2838b",["Text"]="-----------------------------------\n-- ID: 4603\n-- Item: cup_of_chamomile_tea\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Magic 8\n-- Vitality -2\n-- Charisma 2\n-- Magic Regen While Healing 1\n-- Sleep resistance -30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 8)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.CHR, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.SLEEPRES, -30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cup_of_choco-delight.lua"]={["Path"]="scripts/items/cup_of_choco-delight.lua",["SHA256"]="6c1ebe6c5bfc2bc71cb9da97298c13f5897971cad0e8c2064263290314246f05",["Text"]="-----------------------------------\n-- ID: 4283\n-- Item: cup_of_choco-delight\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Magic Regen While Healing 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\n